//! A query's fetch: a hit is one table lookup; a miss runs the query once, single-flighted.

use std::{fmt::Debug, hash::Hash, ptr};

use crate::{
    Cancelled, Cycle, Kind, MAX_ROUNDS, Memo,
    arena::{Slot, with_local},
    counts,
    flight::{FlightKey, Flown, Hold},
    home::{Home, home_of, mark_borrows},
    task::{self, Role, Run},
    trie::{Entry, Head},
};

/// A query: generated by `#[blaze_memo::tracked]`, one zero-sized type per function.
pub trait Query: 'static {
    /// The arguments after `db`, as a tuple, in their stored (`'static`) form.
    type Key: Copy + Eq + Hash + Home + Debug + Send + Sync + 'static;
    /// The value, in its stored form. Owns no memory to drop.
    type Value: Send + Sync + 'static;
    const KIND: &'static Kind;
}

/// What a query does when its key is asked inside its own run: its `cycle_*` options.
pub enum Recovery<'a, V> {
    /// No recovery: the cycle panics naming its path.
    Panic,
    /// `cycle_result`: the fallback of this key.
    Result(&'a dyn Fn() -> V),
    /// `cycle_initial`, `cycle_fn` and the value's equality.
    Fixpoint {
        initial: &'a dyn Fn() -> V,
        recover: Option<&'a dyn Fn(&Cycle<'_>, &V, V) -> V>,
        same: fn(&V, &V) -> bool,
    },
}

/// How many times one fetch asks the flight before it gives up: each further ask follows a run
/// that ended without an entry (it panicked, or it was a fixpoint member, memoized only once
/// its head settles).
const ASKS: u32 = 1 << 16;

pub(crate) fn hash_of<K: Hash + ?Sized>(kind: &Kind, key: &K) -> u64 {
    use std::hash::{BuildHasher, Hasher};
    let mut hasher = blaze_hash::FixedState.build_hasher();
    hasher.write_u64(kind.id());
    key.hash(&mut hasher);
    hasher.finish()
}

/// The entry of `Q` for `key` in `slot`, or in the snapshot's spill table when a successor took
/// `slot`.
#[inline]
pub(crate) fn lookup<'db, K: Eq + 'static, V: 'static>(
    memo: &'db Memo,
    slot: &'db Slot,
    kind: &'static Kind,
    hash: u64,
    key: &K,
) -> Option<&'db Head> {
    let same = |head: &Head| {
        // SAFETY: the kind is checked first, and an entry of `kind` is an `Entry<K, V>`.
        ptr::eq(head.kind, kind) && unsafe { Entry::<K, V>::of(head) }.key == *key
    };
    if let Some(head) = slot.trie.get(hash, same) {
        return Some(head);
    }
    if slot.writable_by(memo.epoch()) {
        return None;
    }
    // A key has one home, so the spill table needs no arena in its keys.
    memo.spill().trie.get(hash, same)
}

/// Publishes `head` (an `Entry<K, V>` in `slot`'s arena) in `slot`, or in the spill table when a
/// successor took `slot`. Gives the entry already there when one is.
pub(crate) fn publish<'db, K: Eq + 'static, V: 'static>(
    memo: &'db Memo,
    slot: &'db Slot,
    head: &'db Head,
) -> Result<(), &'db Head> {
    let kind = head.kind;
    // SAFETY: the caller's: `head` is an `Entry<K, V>`'s.
    let key: &K = &unsafe { Entry::<K, V>::of(head) }.key;
    let same = |other: &Head| {
        // SAFETY: as in `lookup`.
        ptr::eq(other.kind, kind) && unsafe { Entry::<K, V>::of(other) }.key == *key
    };
    let into_slot = slot.write(memo.epoch(), || {
        with_local(slot, |local| slot.trie.insert(local, head, &same))
    });
    match into_slot {
        Some(result) => result,
        None => {
            counts::spill();
            // The entry stays in `slot`'s arena (this snapshot holds it); only its index is
            // the spill table's.
            let spill = memo.spill();
            with_local(spill, |local| spill.trie.insert(local, head, &same))
        }
    }
}

/// The value of `Q` for `key` in `memo`: found, waited for, or run here by `run`.
///
/// # Panics
///
/// Where the run panics (the panic goes on; a waiter asks again and runs it itself), where a
/// cycle has no recovery, or where a fixpoint does not settle in [`MAX_ROUNDS`].
pub fn fetch<'db, Q: Query>(
    memo: &'db Memo,
    key: Q::Key,
    run: &dyn Fn() -> Q::Value,
    recovery: &Recovery<'_, Q::Value>,
) -> &'db Q::Value {
    const { crate::plumbing::assert_no_drop::<Q::Value>() };
    let slot = memo.slot(home_of(&key));
    task::note_read_of(memo, slot);
    let hash = hash_of(Q::KIND, &key);
    if let Some(head) = lookup::<Q::Key, Q::Value>(memo, slot, Q::KIND, hash, &key) {
        counts::hit();
        if memo.plant() == crate::Plant::HitChecks {
            for _ in head.reads() {
                counts::hit_check();
            }
            counts::hit_check();
        }
        task::replay(memo, head);
        // SAFETY: an entry of `Q::KIND` is an `Entry<Q::Key, Q::Value>`.
        return &unsafe { Entry::<Q::Key, Q::Value>::of(head) }.value;
    }
    let key_ptr = ptr::from_ref(&key).cast::<()>();
    let provisional = task::provisional(Q::KIND, hash, key_ptr);
    if !provisional.is_null() {
        // SAFETY: a provisional value of `Q::KIND` is a `Q::Value` in an arena of `memo`.
        return unsafe { &*provisional.cast::<Q::Value>() };
    }
    counts::miss();
    if task::here(Q::KIND, hash, key_ptr) == task::Here::Kept {
        // A fixpoint member of an earlier round of a head on this task's stack, which holds
        // its flight still: its next round runs here, and no other task can be running it.
        return execute::<Q>(memo, slot, hash, &key, run, recovery).0;
    }
    let flight = FlightKey::of(Q::KIND, slot.id, hash);
    let named = |out: &mut String| {
        // SAFETY: `key_ptr` points at `key`, a `Q::Key`.
        unsafe { task::describe::<Q::Key>(Q::KIND, key_ptr, out) }
    };
    for _ in 0..ASKS {
        let mut out: Option<&'db Q::Value> = None;
        let mut member: Option<task::Member> = None;
        let mut body = || {
            if let Some(head) = lookup::<Q::Key, Q::Value>(memo, slot, Q::KIND, hash, &key) {
                task::replay(memo, head);
                // SAFETY: as above.
                out = Some(&unsafe { Entry::<Q::Key, Q::Value>::of(head) }.value);
                return Hold::End;
            }
            let (value, of) = execute::<Q>(memo, slot, hash, &key, run, recovery);
            out = Some(value);
            match of {
                Some(of) if memo.plant() != crate::Plant::MemberLetGo => {
                    member = Some(of);
                    Hold::Keep
                }
                _ => Hold::End,
            }
        };
        match memo.flight().single(flight, &named, &mut body) {
            Flown::Ran => {
                return out.expect("a run that returned left its value");
            }
            Flown::Kept(kept) => {
                task::keep_flight(member.take().expect("a run that kept its key is a member's"), kept);
                return out.expect("a run that returned left its value");
            }
            Flown::Waited => {
                counts::wait();
                if let Some(head) = lookup::<Q::Key, Q::Value>(memo, slot, Q::KIND, hash, &key) {
                    task::replay(memo, head);
                    // SAFETY: as above.
                    return &unsafe { Entry::<Q::Key, Q::Value>::of(head) }.value;
                }
            }
            Flown::Mine => {
                let value = task::reenter(Q::KIND, hash, key_ptr, || {
                    let value = match recovery {
                        Recovery::Result(fallback) => fallback(),
                        Recovery::Fixpoint { initial, .. } => initial(),
                        Recovery::Panic => unreachable!("`reenter` refuses a query with no recovery"),
                    };
                    ptr::from_ref(keep_in(slot, value)).cast()
                });
                // SAFETY: as for `provisional`.
                return unsafe { &*value.cast::<Q::Value>() };
            }
            Flown::Cancelled => Cancelled::GaveWay.throw(),
        }
    }
    let mut name = String::new();
    named(&mut name);
    panic!("{name} was asked {ASKS} times and each run it waited for ended without a value");
}

/// `value` moved into `slot`'s arena.
pub(crate) fn keep_in<V>(slot: &Slot, value: V) -> &V {
    let at = with_local(slot, |local| -> *const V { local.alloc(value) });
    // SAFETY: in `slot`'s arena, which lives as long as the slot.
    unsafe { &*at }
}

/// Runs `Q` for `key` on this task, settles its cycle role, and publishes a final value; a
/// fixpoint member's value is published by its head instead, and the member is returned so its
/// head keeps its flight until then.
fn execute<'db, Q: Query>(
    memo: &'db Memo,
    slot: &'db Slot,
    hash: u64,
    key: &Q::Key,
    run: &dyn Fn() -> Q::Value,
    recovery: &Recovery<'_, Q::Value>,
) -> (&'db Q::Value, Option<task::Member>) {
    counts::run();
    let frame = Run::new(memo, Q::KIND, slot, hash, key);
    let pushed = task::push(&frame);
    let mut round = 0;
    let value = loop {
        let value = run();
        match (frame.role(), recovery) {
            (Role::Plain, _) => break Settled::Final(value),
            (Role::Head | Role::Member, Recovery::Result(fallback)) => {
                break Settled::Final(fallback());
            }
            (Role::Head, Recovery::Fixpoint { recover, same, .. }) => {
                // SAFETY: a head was reentered, so its provisional value is set, a `Q::Value`.
                let last = unsafe { &*frame.provisional().cast::<Q::Value>() };
                let this_round = frame.round();
                let members_moved = frame.next_round();
                if same(last, &value) && !members_moved {
                    frame.settle_members(memo, this_round);
                    frame.end_cycle();
                    break Settled::Final(value);
                }
                round += 1;
                assert!(
                    round < MAX_ROUNDS,
                    "{} did not settle in {MAX_ROUNDS} rounds",
                    task::innermost_name().unwrap_or_default()
                );
                let next = match recover {
                    Some(recover) => {
                        let cycle = Cycle {
                            head: Q::KIND,
                            round: round - 1,
                            _memo: std::marker::PhantomData,
                        };
                        recover(&cycle, last, value)
                    }
                    None => value,
                };
                frame.set_provisional(ptr::from_ref(keep_in(slot, next)).cast());
            }
            (Role::Member, Recovery::Fixpoint { same, .. }) => {
                let moved = if frame.provisional().is_null() {
                    false
                } else {
                    // SAFETY: as above.
                    let last = unsafe { &*frame.provisional().cast::<Q::Value>() };
                    !same(last, &value)
                };
                let at = keep_in(slot, value);
                let key_copy = keep_in(slot, *key);
                let reads = frame.take_reads();
                let kept = with_local(slot, |local| -> *const [crate::Fact] {
                    local.alloc_slice_copy(&reads)
                });
                let settle = task::Settle {
                    slot: ptr::from_ref(slot),
                    reads: kept,
                    publish: publish_member::<Q::Key, Q::Value>,
                };
                task::member_done(
                    &frame,
                    ptr::from_ref(key_copy).cast(),
                    ptr::from_ref(at).cast(),
                    moved,
                    settle,
                );
                break Settled::Provisional(at, reads, frame.member(ptr::from_ref(key_copy).cast()));
            }
            (_, Recovery::Panic) => {
                unreachable!("`reenter` refuses a cycle through a query with no recovery")
            }
        }
    };
    let reads = match &value {
        Settled::Provisional(_, reads, _) => reads.clone(),
        Settled::Final(_) => frame.take_reads(),
    };
    drop(pushed);
    // The asker depends on what this run read.
    task::replay_list(&reads);
    match value {
        Settled::Provisional(at, _, member) => (at, Some(member)),
        Settled::Final(value) => {
            mark_borrows(memo, slot, key);
            let entry = with_local(slot, |local| -> *const Entry<Q::Key, Q::Value> {
                let reads = local.alloc_slice_copy(&reads);
                local.alloc(Entry {
                    head: Head::new(hash, Q::KIND, reads, 0),
                    key: *key,
                    value,
                })
            });
            // SAFETY: just made in `slot`'s arena, which `memo` holds.
            let entry: &'db Entry<Q::Key, Q::Value> = unsafe { &*entry };
            match publish::<Q::Key, Q::Value>(memo, slot, &entry.head) {
                Ok(()) => (&entry.value, None),
                Err(_) => {
                    let mut name = String::new();
                    // SAFETY: `key` is a `Q::Key`.
                    unsafe { task::describe::<Q::Key>(Q::KIND, ptr::from_ref(key).cast(), &mut name) };
                    panic!(
                        "{name} ran twice in one snapshot: two runs of one key passed the flight"
                    )
                }
            }
        }
    }
}

enum Settled<'db, V> {
    Final(V),
    /// A fixpoint member's value this round, what it read, and who keeps its flight.
    Provisional(&'db V, Vec<crate::Fact, std::alloc::Global>, task::Member),
}

/// Publishes a fixpoint member's last-round value as its entry, once its head settled.
///
/// # Safety
///
/// `key` and `value` point at a `K` and a `V` in `slot`'s arena, which `memo` holds.
unsafe fn publish_member<K: Copy + Eq + Home + 'static, V: 'static>(
    memo: &Memo,
    slot: &Slot,
    kind: &'static Kind,
    hash: u64,
    key: *const (),
    value: *const (),
    reads: &[crate::Fact],
) {
    // SAFETY: the caller's.
    let (key, value) = unsafe { (*key.cast::<K>(), ptr::read(value.cast::<V>())) };
    // A bitwise copy of a value that owns nothing to drop: the original in the arena is never
    // dropped, and both are immutable.
    mark_borrows(memo, slot, &key);
    let entry = with_local(slot, |local| -> *const Entry<K, V> {
        let reads = local.alloc_slice_copy(reads);
        local.alloc(Entry { head: Head::new(hash, kind, reads, 0), key, value })
    });
    // SAFETY: just made in `slot`'s arena, which `memo` holds.
    let entry: &Entry<K, V> = unsafe { &*entry };
    // The head has held the member's flight since the member's first run here, so no other
    // task ran it: an entry already there is two runs of one key in one snapshot.
    if publish::<K, V>(memo, slot, &entry.head).is_err() {
        panic!(
            "{} ran twice in one snapshot: a fixpoint member was run by another task while its \
             head held it",
            kind.name()
        );
    }
}
